        let tracked (dealloc0, points_to_raw0) = dealloc_inner.into_user(points_to_r, size as int);

        dealloc = dealloc0;
        points_to_raw = points_to_raw0;


        preserves_mem_chunk_good(*old(local), *local);
    }

    (ptr, Tracked(points_to_raw), Tracked(dealloc))
}


